export default function MaryMagdalene({ p }: PortraitProps) {
  return (
    <>
      {/* Paintable paper/background. */}
      <g {...p('background')} stroke="none">
        <rect x="0" y="0" width="640" height="700" />
      </g>

      {/* Hooded veil and outer mantle. */}
      <g {...p('mantle')} stroke="none" transform={`translate(${ART_X} 0)`}>
        <path d={MARY_MANTLE_MASK} fillRule="evenodd" />
      </g>

      {/* Inner tunic, sleeves, and dress. */}
      <g {...p('robe')} stroke="none" transform={`translate(${ART_X} 0)`}>
        <path d={MARY_ROBE_MASK} fillRule="evenodd" />
      </g>

      {/* Veil trim, cuffs, sash, and decorative bands. */}
      <g {...p('accent')} stroke="none" transform={`translate(${ART_X} 0)`}>
        <path d={MARY_ACCENT_MASK} fillRule="evenodd" />
      </g>

      {/* Long wavy hair. */}
      <g {...p('hair')} stroke="none" transform={`translate(${ART_X} 0)`}>
        <path d={MARY_HAIR_MASK} fillRule="evenodd" />
      </g>

      {/* Alabaster jar. */}
      <g {...p('symbol')} stroke="none" transform={`translate(${ART_X} 0)`}>
        <path d={MARY_SYMBOL_MASK} fillRule="evenodd" />
      </g>

      {/* Face, ear, neck, and hands. */}
      <g {...p('skin')} stroke="none" transform={`translate(${ART_X} 0)`}>
        <path d={MARY_SKIN_MASK} fillRule="evenodd" />
      </g>

      {/* Pixel-matched black outline and background architecture. */}
      <path
        d={MARY_LINE_ART}
        transform={`translate(${ART_X} 0) scale(${ART_SCALE_X} ${ART_SCALE_Y})`}
        fillRule="evenodd"
        {...ink}
      />
    </>
  );
}